export function featuredPlan(
  code: string,
  countries: string[] = coverage.europe,
  dataGb = 10,
  days = 30,
  price = 1999,
): StoredPlan {
  return pricePackage(
    {
      id: catalogueId(code),
      name: 'Supplier product ' + code,
      countries,
      dataGb,
      days,
      priceCents: price,
      currency: 'USD',
      dataType: 'fixed',
      activation: 'Starts on first connection.',
      fairUse: 'Fixed allowance.',
      networks: [],
      syncedAt: at.toDate().toISOString(),
      demo: false,
      active: true,
      supplierCode: code,
      providerId: 'esim-access',
      wholesaleUnits: 10000,
    },
    { priceOverrideUsdCents: price },
    at,
  );
}
